use chrono::{DateTime, Utc};
use exchange_common::{OrderType, Side, Symbol, UserId};
use rust_decimal::Decimal;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// An order generated by an algo execution algorithm to be submitted to the matching engine.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AlgoOrder {
    pub user_id: UserId,
    pub symbol: Symbol,
    pub side: Side,
    pub qty: Decimal,
    pub order_type: OrderType,
    /// Limit price. `None` for market orders.
    pub price: Option<Decimal>,
}

/// Overall status of an algo execution.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum AlgoStatus {
    /// Execution is ongoing; slices are being submitted.
    Active,
    /// All slices have been submitted and filled.
    Completed,
    /// Execution was cancelled by the user.
    Cancelled,
    /// Halted because the market price crossed the configured price limit.
    PriceLimitBreached,
}

/// Status of an individual slice within an algo execution.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SliceStatus {
    /// Not yet due for submission.
    Pending,
    /// Order has been submitted to the matching engine.
    Submitted,
    /// Slice was fully filled.
    Filled,
    /// Slice was partially filled (e.g., IOC order with partial execution).
    PartiallyFilled,
    /// Submission or fill failed.
    Failed,
}

/// Controls how each slice order is priced.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SliceOrderType {
    /// Market order — immediate execution at any price.
    Market,
    /// Limit order placed exactly at the mid-price (best bid/ask midpoint).
    LimitAtMid,
    /// Limit order placed one tick inside the spread toward the opposite side,
    /// increasing the chance of a fill while still avoiding crossing.
    LimitAggressive,
}

/// Computes the limit price for a slice given the mid-price and order type.
///
/// For `LimitAtMid` the price equals `mid_price` (rounded to provided `tick_size`).
/// For `LimitAggressive` the price is nudged by one tick in the aggressive direction:
/// buy orders price slightly higher, sell orders price slightly lower.
pub fn compute_limit_price(
    mid_price: Decimal,
    order_type: SliceOrderType,
    side: Side,
    tick_size: Decimal,
) -> Option<Decimal> {
    match order_type {
        SliceOrderType::Market => None,
        SliceOrderType::LimitAtMid => Some(mid_price),
        SliceOrderType::LimitAggressive => {
            let adjusted = match side {
                Side::Buy => mid_price + tick_size,
                Side::Sell => mid_price - tick_size,
            };
            Some(adjusted)
        }
    }
}

/// Computes a running volume-weighted average fill price.
///
/// Returns `None` when `total_fill_qty` is zero to avoid division by zero.
pub fn weighted_avg_price(
    prev_avg: Decimal,
    prev_qty: Decimal,
    new_price: Decimal,
    new_qty: Decimal,
) -> Decimal {
    let total_qty = prev_qty + new_qty;
    if total_qty.is_zero() {
        return Decimal::ZERO;
    }
    (prev_avg * prev_qty + new_price * new_qty) / total_qty
}

/// Timestamp used as the epoch for slice scheduling in tests.
pub fn utc_now() -> DateTime<Utc> {
    Utc::now()
}

/// Generates a fresh algo execution ID.
pub fn new_algo_id() -> Uuid {
    Uuid::new_v4()
}
